public static void check(Solution solution) {
    assert Arrays.equals(solution.isMonotonic(new int[]{1,2,2,3}), True);
    assert Arrays.equals(solution.isMonotonic(new int[]{1,2,4,5}), True);
    assert Arrays.equals(solution.isMonotonic(new int[]{-1,-2,-2,-3}), True);
    assert Arrays.equals(solution.isMonotonic(new int[]{1,1,1,1}), True);
    assert Arrays.equals(solution.isMonotonic(new int[]{1,1,1}), True);
    assert Arrays.equals(solution.isMonotonic(new int[]{10,-10,-20,-30}), True);
    assert Arrays.equals(solution.isMonotonic(new int[]{-100,0,100}), True);
    assert Arrays.equals(solution.isMonotonic(new int[]{-100000,100000}), True);
    assert Arrays.equals(solution.isMonotonic(new int[]{1,2,2,1}), False);
    assert Arrays.equals(solution.isMonotonic(new int[]{1}), True);
    assert Arrays.equals(solution.isMonotonic(new int[]{5,3,3,2,1}), True);
    assert Arrays.equals(solution.isMonotonic(new int[]{-1,-5,-10,-10}), True);
    assert Arrays.equals(solution.isMonotonic(new int[]{6,5,4,4}), True);
    assert Arrays.equals(solution.isMonotonic(new int[]{100000, -100000, 0}), False);
    assert Arrays.equals(solution.isMonotonic(new int[]{1,3,2}), False);
    assert Arrays.equals(solution.isMonotonic(new int[]{100000,-100000}), True);
    assert Arrays.equals(solution.isMonotonic(new int[]{4,4,4,4}), True);
    assert Arrays.equals(solution.isMonotonic(new int[]{-100000, 0, 100000}), True);
    assert Arrays.equals(solution.isMonotonic(new int[]{-1,-2,-3,-4}), True);
    assert Arrays.equals(solution.isMonotonic(new int[]{5,5,4,4,3,3,2,2}), True);
    assert Arrays.equals(solution.isMonotonic(new int[]{100,90,90,80,70,60,50}), True);
    assert Arrays.equals(solution.isMonotonic(new int[]{5,3,2,4,1}), False);
    assert Arrays.equals(solution.isMonotonic(new int[]{1,2,4,5,6,7,8}), True);
    assert Arrays.equals(solution.isMonotonic(new int[]{5}), True);
